WITH with_last AS (SELECT s.*, top1.end_date FROM customers s LEFT JOIN LATERAL (SELECT c.end_date FROM subscriptions c WHERE c.customer_id = s.id ORDER BY c.monthly_fee DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_windows AS (SELECT *, CUME_DIST() OVER (PARTITION BY city ORDER BY age DESC NULLS LAST) AS age_cume_dist, NTILE(4) OVER w_recent AS age_bucket FROM with_last WHERE end_date < '2025-08-01' WINDOW w_recent AS (PARTITION BY country, segment ORDER BY age, id)), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, segment ORDER BY age_bucket DESC, id) AS row_num FROM with_windows QUALIFY row_num = 1), scored AS (SELECT id, name, email, signup_date, is_active, credit_limit, end_date, age_cume_dist, age_bucket, row_num, MIN(age_bucket) OVER (PARTITION BY segment) AS segment_min_age_bucket, SUM(credit_limit) OVER (PARTITION BY city ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_credit_limit, AVG(age_cume_dist) OVER (PARTITION BY city) AS city_avg_age_cume_dist, ROW_NUMBER() OVER (PARTITION BY segment ORDER BY age, id) AS event_seq, FIRST_VALUE(age_bucket, TRUE) OVER (PARTITION BY city ORDER BY row_num, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_age_bucket FROM ranked), enriched AS (SELECT *, AVG(cumulative_credit_limit) OVER w_recent AS running_avg_cumulative_credit_limit, SUM(cumulative_credit_limit) OVER w_recent AS running_sum_cumulative_credit_limit, MAX(cumulative_credit_limit) OVER w_recent AS running_max_cumulative_credit_limit, COUNT(cumulative_credit_limit) OVER w_recent AS running_count_cumulative_credit_limit FROM scored WINDOW w_recent AS (ORDER BY segment_min_age_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, name, email, signup_date, is_active, credit_limit, end_date, age_cume_dist, age_bucket, CASE WHEN name RLIKE '^(Henry Ford|Mia Rossi)$' THEN 'PRIORITY' WHEN name RLIKE '^(Alice Wong|bob smith)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS name_zone FROM enriched ORDER BY signup_date, name_zone;
